    correctKey: 'C',
    explanation: '骨材の含水状態は、乾いている順に絶対乾燥状態（絶乾）、空気中乾燥状態（気乾）、表面乾燥飽水状態（表乾）、湿潤状態の4つに区分される。絶乾は内部空隙の水もすべて失った状態、気乾は表面と内部の一部が乾燥した状態、表乾は内部空隙が水で満たされ表面のみ乾いた状態、湿潤は内部が飽水しさらに表面にも水が付着した状態である。示方配合の骨材質量は表乾状態を基準とするため、現場の骨材が表乾より乾いていれば不足分（有効吸水量）を練混ぜ水に加え、湿っていれば表面水量を練混ぜ水から差し引く。この補正を怠ると水セメント比が設計値からずれ、強度や耐久性に直接影響する。\n\n【図解】含水状態と水量の関係\n　状態｜内部空隙｜表面｜配合補正\n　絶乾｜空｜乾燥｜吸水率分を加水\n　気乾｜一部含水｜乾燥｜有効吸水量を加水\n　表乾｜飽水｜乾燥｜補正不要（基準）\n　湿潤｜飽水｜水が付着｜表面水量を減水\n　⚠ 吸水率は絶乾質量基準、表面水率は表乾質量基準で計算する。',
    difficulty: 'basic',
