    explanation: 'セメントの物理試験はJIS R 5201に規定されている。粉末度はブレーン空気透過装置で比表面積として測定し、普通ポルトランドセメントで2500平方センチメートル毎グラム以上、早強ポルトランドセメントで3300以上が規格値である。粉末度が高いほど水和が速く初期強度が高いが、水和熱と乾燥収縮も大きくなる。凝結試験はビカー針装置を用い、標準軟度のペーストに対する針の貫入量で始発と終結を判定する。普通ポルトランドセメントの規格は始発60分以上、終結10時間以下である。安定性試験は遊離石灰や遊離マグネシアによる異常膨張の有無を調べるもので、パット法とオートクレーブ法がある。強さ試験は水セメント比0.50のモルタルで角柱供試体を作製し、曲げ強さと圧縮強さを測定する。密度はルシャテリエフラスコで測定し、普通ポルトランドセメントで3.15グラム毎立方センチメートル程度である。\n\n【図解】セメントの主な物理試験\n　試験項目｜装置・方法｜規格値の例\n　粉末度｜ブレーン空気透過装置｜普通で2500以上\n　凝結｜ビカー針装置｜始発60分以上、終結10時間以下\n　安定性｜パット法・オートクレーブ法｜異常のないこと\n　密度｜ルシャテリエフラスコ｜普通で約3.15\n　⚠ 粉末度の単位は平方センチメートル毎グラム、密度はグラム毎立方センチメートル。',
