    correctKey: 'A',
    explanation: '実積率とは、容器に詰めた骨材の見かけの容積のうち、骨材の実質部分が占める割合をいい、単位容積質量を骨材の密度で除して百分率で表す。空隙率は残りの部分であり、100から実積率を引いた値となる。実積率は骨材の粒形と粒度を反映する指標で、球形に近く粒度分布が良好なほど大きくなる。実積率が大きい骨材ほど骨材間の空隙が少なく、その空隙を埋めるためのセメントペースト量が少なくてすむため、単位水量および単位セメント量を減らすことができ、乾燥収縮や水和熱の面でも有利となる。砂利は実積率が大きく、砕石は角ばっているため実積率が小さい。砕石の粒形の良否は粒形判定実積率で評価され、粗骨材で56パーセント以上、砕砂で54パーセント以上が目安とされる。\n\n【図解】実積率の計算例\n　・式 → 実積率＝単位容積質量÷密度×100\n　・代入 → 1.60÷2.65×100\n　・結果 → 60.4パーセント\n　・空隙率 → 100−60.4＝39.6パーセント\n　⚠ 単位容積質量はキログラム毎リットル、密度はグラム毎立方センチメートルで数値を揃える。',
