    explanation: '硬化促進剤は、セメントの水和反応を促進して凝結を早め、初期強度の発現を高める混和剤である。寒中コンクリートにおける初期凍害の防止、工期短縮、吹付けコンクリートやグラウトの早期強度確保などに用いられる。代表的な成分は塩化カルシウムであるが、塩化物イオンが鉄筋の不動態被膜を破壊して腐食を促進するため、鉄筋コンクリートやプレストレストコンクリートでは使用が厳しく制限される。このため現在は亜硝酸カルシウムやチオシアン酸塩など非塩化物系の促進剤が主流である。促進剤を用いると水和が急速に進むため、凝結時間が短くなり打重ね時間間隔の管理が難しくなること、水和熱の発生が早まること、乾燥収縮が大きくなり長期強度が伸びにくいことに留意する。\n\n【図解】促進剤と遅延剤の対比\n　項目｜促進剤｜遅延剤\n　凝結｜早める｜遅らせる\n　主な用途｜寒中コンクリート、吹付け｜暑中コンクリート、マスコン、長距離運搬\n　代表成分｜塩化カルシウム、亜硝酸塩｜オキシカルボン酸塩、糖類\n　留意点｜鉄筋腐食、収縮増大｜過剰添加で強度発現が著しく遅延\n　⚠ 塩化カルシウムは鉄筋コンクリートには原則使わない。',
