    explanation: '骨材に含まれる有害物は、コンクリートの強度、耐久性、ワーカビリティーに悪影響を及ぼすため、JIS A 5308附属書などで上限が定められている。有機不純物は腐植土などに由来し、セメントの水和を阻害して凝結遅延や強度低下を招くため、水酸化ナトリウム溶液を用いた呈色試験で判定し、標準色液より濃い場合はモルタルの圧縮強度比が90パーセント以上であることを確認する。粘土塊は骨材とペーストの付着を弱めるうえ自身が収縮するため、細骨材で1.0パーセント以下、粗骨材で0.25パーセント以下とされる。微粒分量は0.075ミリメートルふるいを通過する微細な粒で、比表面積が大きく単位水量を増やすため、砕石で3.0パーセント以下、砕砂で7.0パーセント以下（品質に悪影響のない場合9.0パーセント以下）と定められている。塩化物は鉄筋腐食の原因となり、塩化ナトリウム換算で0.04パーセント以下である。\n\n【図解】骨材中の有害物の規定値\n　有害物｜細骨材｜粗骨材\n　粘土塊量｜1.0パーセント以下｜0.25パーセント以下\n　微粒分量｜7.0パーセント以下｜3.0パーセント以下\n　塩化物量（NaCl換算）｜0.04パーセント以下｜規定なし\n　軟石量｜規定なし｜5.0パーセント以下\n　⚠ 有機不純物は呈色試験、耐久性は硫酸ナトリウムによる安定性試験で確認する。',
