    correctKey: 'A',
    explanation: 'セメントの粉末度はブレーン空気透過装置により比表面積として測定される。粉末度が高い、すなわち粒子が細かいほど、水と接触する表面積が増えるため水和反応が速く進む。その結果、初期強度が高くなり、凝結が早まり、水和熱の発生速度が大きくなる。またワーカビリティーが改善されブリーディングは少なくなる。一方、望ましくない側面として、乾燥収縮とひび割れが大きくなること、水和熱が大きいためマスコンクリートで温度ひび割れを生じやすいこと、比表面積が大きいため貯蔵中に風化しやすいことが挙げられる。早強ポルトランドセメントは比表面積を3300平方センチメートル毎グラム以上と高くして初期強度を確保しており、逆に低熱ポルトランドセメントは粉末度を抑えることも水和熱低減に寄与している。\n\n【図解】粉末度が高いときの影響\n　・初期強度 → 高くなる\n　・凝結時間 → 短くなる\n　・水和熱の発生速度 → 大きくなる\n　・ブリーディング → 少なくなる\n　⚠ 乾燥収縮と風化のしやすさも増える。良いことばかりではない。',
    difficulty: 'standard',
