    explanation: '骨材の耐久性に関する試験には、すりへり試験と安定性試験がある。すりへり試験はロサンゼルス試験機に粗骨材と鋼球を入れて回転させ、破砕・摩耗により1.7ミリメートルふるいを通過した質量の割合をすりへり減量として求める。限度は一般のコンクリート用粗骨材で40パーセント以下、舗装コンクリート用粗骨材で35パーセント以下である。安定性試験は、硫酸ナトリウムの飽和溶液に骨材を浸してから乾燥する操作を5回繰り返し、結晶の生成圧により生じる骨材の破壊量を損失質量の百分率で評価するもので、凍結融解作用に対する抵抗性の代替指標とされる。損失質量の限度は細骨材で10パーセント以下、粗骨材で12パーセント以下である。このほか骨材の凍結融解に対する直接的な評価としては、コンクリートとしての凍結融解試験（相対動弾性係数）が用いられる。\n\n【図解】骨材の耐久性試験\n　試験｜対象｜限度\n　すりへり試験（一般用）｜粗骨材｜40パーセント以下\n　すりへり試験（舗装用）｜粗骨材｜35パーセント以下\n　安定性試験｜細骨材｜10パーセント以下\n　安定性試験｜粗骨材｜12パーセント以下\n　⚠ 安定性試験の薬品は硫酸ナトリウム。塩化ナトリウムではない。',
    difficulty: 'standard',
