    correctKey: 'A',
    explanation: '砕石や砕砂は岩石を破砕して製造するため、粒形が角ばったり扁平・細長になったりしやすい。粒形が悪いと骨材間の空隙が増え、同一のワーカビリティーを得るために単位水量と単位セメント量が増加し、乾燥収縮や水和熱の面で不利になる。この粒形の良否を客観的に評価する指標が粒形判定実積率である。試料の粒度を規定の割合に調整したうえで実積率を測定するため、粒度の影響を排除して純粋に粒形のみを評価できる。JIS A 5005では砕石で56パーセント以上、砕砂で54パーセント以上と規定されている。値が大きいほど球形に近く粒形が良好であることを示す。なお通常の実積率は粒度の影響も含むため、粒形の比較には粒形判定実積率を用いる。川砂利は粒形が丸いため実積率が大きく、単位水量の面で有利である。\n\n【図解】粒形判定実積率の規定\n　骨材｜規定値｜意味\n　砕石｜56パーセント以上｜値が大きいほど粒形良好\n　砕砂｜54パーセント以上｜値が大きいほど粒形良好\n　⚠ 粒度を規定どおりに調整して測る点が、通常の実積率との違いである。',
