    correctKey: 'B',
    explanation: '吸水率とは、骨材が表面乾燥飽水状態になるまでに内部の空隙に吸収する水の量を、絶対乾燥状態の骨材質量に対する百分率で表したものである。式で書けば、吸水率イコール（表乾質量ひく絶乾質量）わる絶乾質量かける100である。表面水率が表乾質量を基準とするのに対し、吸水率は絶乾質量を基準とする点が最大の相違点であり、試験ではここを入れ替えた誤答肢が必ず用意される。本問では吸水量が512.5ひく500で12.5グラム、これを絶乾質量500グラムで除して100を乗じると2.50パーセントとなる。吸水率は骨材の多孔性を示す指標であり、値が大きい骨材は耐凍害性や乾燥収縮の面で不利になる。JISでは砕石、砕砂とも3.0パーセント以下と規定されている。\n\n【図解】吸水率と表面水率の基準の違い\n　指標｜分子｜分母\n　吸水率｜表乾質量−絶乾質量｜絶乾質量\n　表面水率｜湿潤質量−表乾質量｜表乾質量\n　含水率｜含まれる全水量｜絶乾質量\n　⚠ 本問の代入は（512.5−500）÷500×100＝2.50パーセント。',
