    explanation: 'セメントの選定は、構造物が置かれる環境と要求性能から決まる。寒中コンクリートでは初期凍害を防ぐため早期に強度を発現させる必要があり、早強ポルトランドセメントが有効である。マスコンクリートでは水和熱による内部拘束および外部拘束に起因する温度ひび割れが最大の課題であるから、水和熱の小さい中庸熱ポルトランドセメント、低熱ポルトランドセメント、高炉セメントB種、フライアッシュセメントB種を用いるべきであり、水和熱の大きい早強ポルトランドセメントは最も避けるべき選択である。海洋構造物では塩化物イオンの浸透と硫酸塩の作用に対する抵抗性が求められるため、高炉セメントB種やC種が適する。硫酸塩を含む土壌や地下水では耐硫酸塩ポルトランドセメント、または高炉セメントB種以上が用いられる。アルカリシリカ反応が懸念される場合は高炉セメントB種やフライアッシュセメントB種が抑制対策として認められている。\n\n【図解】用途別のセメント選定\n　・寒中コンクリート → 早強ポルトランド\n　・マスコンクリート → 中庸熱、低熱、高炉B種\n　・海洋構造物 → 高炉B種、C種\n　・硫酸塩環境 → 耐硫酸塩、高炉B種以上\n　⚠ 早強は寒中には向くがマスコンには最も向かない。',
