    explanation: 'ポルトランドセメントの化学成分はJIS R 5210に規定されている。酸化マグネシウム（MgO）は5.0パーセント以下と定められており、これは遊離マグネシアが緩慢に水和して異常膨張を引き起こすためである。三酸化硫黄（SO3）はせっこう由来の成分で、種類により3.0から3.5パーセント以下と規定されており、過剰であれば硬化後のエトリンガイト生成による膨張を招く。強熱減量は5.0パーセント以下で、風化の程度を示す指標となる。塩化物イオンは鉄筋腐食の原因となるため0.035パーセント以下である。全アルカリ量は酸化ナトリウムと酸化カリウムを酸化ナトリウム換算で合算した値で、アルカリシリカ反応の抑制のために低アルカリ形では0.75パーセント以下と規定される。これに対しコンクリート中のアルカリ総量の規制値3.0キログラム毎立方メートルは単位も意味も異なるので混同してはならない。\n\n【図解】ポルトランドセメントの化学成分規格\n　成分｜規格値｜理由\n　酸化マグネシウム｜5.0パーセント以下｜異常膨張の防止\n　三酸化硫黄｜3.0から3.5パーセント以下｜エトリンガイトによる膨張防止\n　強熱減量｜5.0パーセント以下｜風化の抑制\n　塩化物イオン｜0.035パーセント以下｜鉄筋腐食の防止\n　⚠ 低アルカリ形の全アルカリ量0.75パーセント以下は、ASR抑制のための規定である。',
    difficulty: 'standard',
