    explanation: '骨材の貯蔵で最も重要なのは、粒度と含水状態を安定させることである。含水状態が変動すると表面水率が変わり、補正を誤れば実際の水セメント比が設計値からずれてしまう。このため貯蔵設備には十分な排水設備を設け、降雨の影響を受けにくい構造とし、下部の水はけをよくして含水状態をなるべく均一に保つ。また、種類別、粒度別、産地別に仕切りを設けて分別貯蔵し、混入を防ぐ。粗骨材を高く積み上げると大きい粒が斜面を転がり落ちて下部に偏る粒度分離が生じるので、積み上げ高さを抑え、必要に応じて仕切り板を用いる。暑中コンクリートでは骨材温度がコンクリート温度に最も大きく影響するため、上屋やシートによる日よけ、散水による冷却を行う。寒中コンクリートでは骨材に氷雪が混入しないよう管理し、必要に応じて加熱する。\n\n【図解】骨材貯蔵の留意点\n　・含水状態の変動 → 排水設備の設置、屋根がけ\n　・粒度分離 → 積み上げ高さを抑え仕切りを設ける\n　・異種骨材の混入 → 種類別・粒度別に分別貯蔵\n　・温度 → 暑中は日よけと散水、寒中は氷雪の除去\n　⚠ 含水状態の変動は水セメント比の変動に直結する最重要管理項目である。',
