    correctKey: 'B',
    explanation: '塩害環境など厳しい条件下では、鉄筋そのものに防食措置を施すことがある。エポキシ樹脂塗装鉄筋は、鉄筋表面に厚さ0.2ミリメートル程度のエポキシ樹脂を粉体塗装したもので、塩化物イオンと酸素の侵入を物理的に遮断する。優れた防食性能をもつ一方、塗膜によりコンクリートとの付着強度が低下するため、定着長や重ね継手長を割り増すなどの設計上の配慮が必要である。また運搬や組立時に塗膜が損傷すると、その部分に腐食が集中するおそれがあるため、傷の補修と丁寧な取扱いが求められる。亜鉛めっき鉄筋は犠牲防食作用により鉄を保護するが、高アルカリ環境で亜鉛が反応して水素ガスを発生し付着を低下させる場合がある。ステンレス鉄筋は最も高い耐食性をもつが高価であり、重要構造物の一部に限定して用いられる。\n\n【図解】防食鉄筋の比較\n　種類｜防食原理｜留意点\n　エポキシ樹脂塗装鉄筋｜塗膜による遮断｜付着低下、塗膜損傷\n　亜鉛めっき鉄筋｜犠牲防食｜水素ガス発生の可能性\n　ステンレス鉄筋｜合金自体の耐食性｜高価\n　⚠ エポキシ塗装は付着が落ちる。定着長や継手長の割増しを忘れない。',
