    correctKey: 'C',
    explanation: '細骨材の密度試験はフラスコを用いて行う。表乾状態の試料をフラスコに入れ、水で標線まで満たしたときの質量から、試料が押しのけた水の質量を求めることで試料の容積を得る。押しのけた水の質量は、水だけで満たしたフラスコの質量に試料質量を加えた値から、試料と水で満たしたフラスコの質量を引いて求める。本問では690たす500ひく1000で190グラムとなり、水の密度が1.00グラム毎立方センチメートルであるからこれがそのまま190立方センチメートルの容積を表す。表乾密度は試料の表乾質量500グラムをこの容積190立方センチメートルで除して2.63グラム毎立方センチメートルとなる。この値はJISが定める絶乾密度2.5グラム毎立方センチメートル以上という規定を満たす一般的な砂の値である。あわせて絶乾質量を測定すれば吸水率も算出できる。\n\n【図解】フラスコ法による表乾密度の計算\n　項目｜計算｜結果\n　押しのけた水の質量｜690＋500−1000｜190グラム\n　試料の容積｜190÷1.00｜190立方センチメートル\n　表乾密度｜500÷190｜2.63\n　⚠ 密度の単位はグラム毎立方センチメートル。分母の求め方を式で覚える。',
