    correctKey: 'D',
    explanation: '混和剤は使用量が微量であるため、正確な計量と均一な分散を確保する目的で水に希釈して用いることが多い。この場合、希釈に用いた水は練混ぜ水の一部であるから、その分を単位水量から差し引かなければ実際の水セメント比が設計値より大きくなってしまう。本問ではまず原液量を求める。単位セメント量340キログラムの1.0パーセントであるから3.4キログラム、密度1.0キログラム毎リットルより3.4リットルである。これを5倍に希釈するので希釈液の総量は3.4掛ける5で17.0リットルとなる。このうち原液分が3.4リットル、希釈水が17.0ひく3.4で13.6リットルである。したがって練混ぜ水から13.6リットルを差し引く。なお混和剤原液そのものも大部分が水であるとして全量を差し引く運用をとる場合もあり、仕様書の定めに従う。\n\n【図解】希釈液の計算\n　項目｜計算｜結果\n　原液量｜340×0.01｜3.4キログラム（3.4リットル）\n　希釈液の総量｜3.4×5｜17.0リットル\n　希釈水｜17.0−3.4｜13.6リットル\n　練混ぜ水の補正｜単位水量から13.6を差引き｜ー\n　⚠ 希釈水を差し引かないと実際の水セメント比が大きくなる。',
