    explanation: 'スラッジ固形分率は、スラッジ固形分の質量をスラッジ水中の水の質量で除して百分率で表した値である。したがってスラッジ水中の水の質量が判明していれば、これに固形分率を乗じてスラッジ固形分の質量を求めることができる。本問では170キログラムに0.02を乗じて3.4キログラムとなる。スラッジ固形分にはセメントの水和物や未水和のセメント、微細な骨材粉が含まれ、わずかながら結合材として働くため、配合設計上は単位セメント量に含めて扱う。すなわち、スラッジ固形分を計上する運用では、単位セメント量からその分を差し引いてセメントを計量する。JIS A 5308ではスラッジ固形分率を3パーセント以下と定めており、この上限を超えると凝結時間や強度への影響が無視できなくなる。またスラッジ固形分の変動が大きいと品質が安定しないため、濃度管理が欠かせない。\n\n【図解】スラッジ固形分の計算\n　項目｜計算｜結果\n　式｜スラッジ水中の水×スラッジ固形分率｜ー\n　代入｜170×0.02｜3.4キログラム\n　配合上の扱い｜単位セメント量に含める｜ー\n　⚠ 固形分率の上限は3パーセント。単位セメント量への計上を忘れない。',
