    explanation: '骨材が化学法で無害でないと判定された場合でも、その骨材が直ちに使用できなくなるわけではない。アルカリシリカ反応の抑制対策は三つあり、いずれかを満たせばよいとされている。第一は、モルタルバー法により材齢6か月の膨張率が0.100パーセント未満であることを確認して無害な骨材として使用する方法である。化学法は迅速法であるため、化学法で無害でないとされた骨材がモルタルバー法では無害と判定されることがある。第二は、高炉セメントB種・C種、フライアッシュセメントB種・C種など抑制効果のある混合セメントを使用する方法である。第三は、コンクリート中のアルカリ総量を酸化ナトリウム換算で3.0キログラム毎立方メートル以下に抑える方法である。逆に単位セメント量を増やす対応はアルカリ総量を増加させるため、抑制どころか反応を促進する誤った対策である。\n\n【図解】化学法で無害でないと判定された場合の選択肢\n　・1 → モルタルバー法で無害を確認する\n　・2 → 高炉B種等の混合セメントを使用する\n　・3 → アルカリ総量を3.0キログラム毎立方メートル以下にする\n　⚠ 単位セメント量を増やすとアルカリ総量が増える。逆効果である。',
