    correctKey: 'C',
    explanation: 'コンクリートの配合設計とは、所要の強度、耐久性、水密性、ひび割れ抵抗性、鋼材を保護する性能、およびワーカビリティーを満足するコンクリートが、できるだけ経済的に得られるように各材料の単位量を定める作業である。基本方針は、所要の品質が得られる範囲で単位水量をできるだけ小さくすることに集約される。単位水量が小さければ、同じ水セメント比でも単位セメント量が減って経済的かつ水和熱が抑えられ、また乾燥収縮とブリーディングが減り、耐久性が向上するからである。手順は、配合強度の設定、水セメント比の決定、スランプと空気量の設定、単位水量の決定、単位セメント量の算出、細骨材率の決定、絶対容積法による骨材量の算出、試し練りによる確認と修正という流れをとる。計算だけで完結させず、必ず試し練りで確認することが求められる。\n\n【図解】配合設計の手順\n　・1 → 配合強度を定める\n　・2 → 水セメント比を定める\n　・3 → スランプ、空気量、単位水量を定める\n　・4 → 単位セメント量と細骨材率を定め骨材量を算出する\n　・5 → 試し練りで確認し修正する\n　⚠ 基本方針は単位水量をできるだけ小さくすること。',
    difficulty: 'basic',
