    explanation: 'コンクリートの圧縮強度は材料や製造条件の変動によりばらつくため、平均強度を設計基準強度に一致させると、およそ半数の試験値が設計基準強度を下回ってしまう。これを避けるため、配合設計では設計基準強度あるいは品質基準強度に対して割増しを加えた配合強度を目標として定める。土木学会示方書では、圧縮強度の試験値が品質基準強度を下回る確率が5パーセント以下となるように配合強度を定めることとしており、この場合の配合強度は品質基準強度に標準偏差の1.645倍を加えた値となる。標準偏差はコンクリートの製造における品質管理の程度を表す指標であり、管理が行き届いてばらつきが小さい工場ほど標準偏差が小さく、必要な割増しも小さくなる。すなわち品質管理の水準がそのまま経済性に結びつく構造になっている。\n\n【図解】配合強度の考え方\n　・設計基準強度 → 構造設計で用いる強度\n　・品質基準強度 → 設計基準強度に耐久性等を考慮した値\n　・配合強度 → 品質基準強度＋割増し\n　・割増しの根拠 → 圧縮強度のばらつき（標準偏差）\n　⚠ 下回る確率5パーセント以下なら割増しは標準偏差の1.645倍。',
