    explanation: 'AEコンクリートの空気量は、耐凍害性の確保と強度の維持を両立するように定められる。JIS A 5308では、普通コンクリート、舗装コンクリート、高強度コンクリートの空気量を4.5パーセント、軽量コンクリートを5.0パーセントとし、いずれも許容差をプラスマイナス1.5パーセントとしている。軽量コンクリートで大きく設定するのは、軽量骨材が多孔質で内部に水を保持するため凍害を受けやすく、より多くのエントレインドエアが必要となるためである。空気量が過小であると耐凍害性が確保できず、過大であると圧縮強度が低下する。空気量1パーセントの増減は圧縮強度の4から6パーセントの増減に相当する。空気量は運搬、圧送、締固め、時間経過によって減少するため、荷卸し地点での測定によって管理する。\n\n【図解】空気量の標準値と許容差\n　種類｜空気量｜許容差\n　普通コンクリート｜4.5パーセント｜プラスマイナス1.5パーセント\n　舗装コンクリート｜4.5パーセント｜プラスマイナス1.5パーセント\n　軽量コンクリート｜5.0パーセント｜プラスマイナス1.5パーセント\n　高強度コンクリート｜4.5パーセント｜プラスマイナス1.5パーセント\n　⚠ 軽量だけ5.0パーセント。許容差はすべて共通で1.5パーセント。',
