    explanation: 'スランプ試験はJIS A 1101に規定され、コンクリートのコンシステンシーを評価する最も基本的な試験である。スランプコーンは高さ30センチメートル、上端内径10センチメートル、下端内径20センチメートルの円錐台形の型枠である。試験手順は、水平で滑らかな平板上にスランプコーンを置き、コンクリートをほぼ等しい量の3層に分けて詰め、各層を突き棒で25回ずつ均等に突く。その後、コンクリート上面をならしてから、スランプコーンを高さ30センチメートルを2から3秒かけて静かに鉛直に引き上げる。コンクリート中央部の下がりを0.5センチメートル単位で測定した値がスランプである。高流動コンクリートのように著しく軟らかい場合はスランプでは差が表れないため、広がりの直径で評価するスランプフロー試験を用いる。\n\n【図解】スランプ試験の要点\n　・スランプコーンの高さ → 30センチメートル\n　・詰め方 → 3層に分け各層25回突く\n　・引上げ → 高さ30センチメートルを2から3秒かけて\n　・読み方 → 頂部の下がりを0.5センチメートル単位\n　⚠ 広がりで測るのはスランプフロー。スランプは下がりで測る。',
