    explanation: 'スランプの許容差はJIS A 5308に規定され、指定したスランプの値に応じて段階的に定められている。スランプ2.5センチメートルの場合はプラスマイナス1センチメートル、2.5センチメートルを超え5センチメートル未満の場合はプラスマイナス1.5センチメートル、5センチメートル以上8センチメートル未満の場合はプラスマイナス1.5センチメートル、8センチメートル以上18センチメートル以下の場合はプラスマイナス2.5センチメートル、21センチメートルの場合はプラスマイナス1.5センチメートルである。8センチメートルから18センチメートルの範囲で許容差が最も大きく、その両側で小さくなっているのは、硬いコンクリートでは絶対値が小さく、軟らかいコンクリートでは材料分離のおそれが大きいためである。荷卸し地点で許容差を外れた場合は、レディーミクストコンクリート工場に連絡して原因を究明し、必要に応じて受入れを拒否する。\n\n【図解】スランプの許容差\n　・2.5センチメートル → プラスマイナス1センチメートル\n　・5以上8未満 → プラスマイナス1.5センチメートル\n　・8以上18以下 → プラスマイナス2.5センチメートル\n　・21センチメートル → プラスマイナス1.5センチメートル\n　⚠ 中間の範囲が最も緩い。21センチメートルは再び厳しくなる。',
