    explanation: '材料分離とは、フレッシュコンクリートを構成する材料の分布が不均一になる現象で、粗骨材が沈降または偏在する分離と、水が浮上するブリーディングに大別される。粗骨材の分離が生じやすい条件は、単位水量が大きくペーストの粘性が低いこと、細骨材率が小さく粗骨材を保持する細粒分が不足していること、粗骨材の最大寸法が大きく密度差が大きいこと、単位セメント量が少なくペースト量が不足していることである。施工面では、自由落下高さが大きいこと、シュートやポンプ配管での落差が大きいこと、過度な振動締固めを行うこと、型枠内での横流しを行うことが原因となる。材料分離が生じると、粗骨材が集中した部分に豆板が生じ、強度のばらつきと耐久性の低下を招くため、配合と施工の両面から防止しなければならない。\n\n【図解】材料分離を生じやすい条件\n　・単位水量 → 大きい\n　・細骨材率 → 小さい\n　・粗骨材の最大寸法 → 大きい\n　・施工 → 自由落下高さが大きい、過度の振動\n　⚠ 分離しにくくするには細骨材率を上げるかAE剤や増粘剤を用いる。',
    difficulty: 'basic',
