    correctKey: 'B',
    explanation: '乾燥収縮は、硬化したコンクリート中の水分が外部へ逸散することにより体積が減少する現象である。収縮するのはセメントペースト部分であり、骨材はこれを拘束する働きをするため、単位水量および単位セメント量が大きいほど、また骨材量が少ないほど収縮は大きくなる。骨材の弾性係数が大きいほど拘束効果が強く収縮は小さい。クリープは、持続的な荷重のもとで時間の経過とともにひずみが増大する現象で、応力が大きいほど、載荷時の材齢が早いほど、水セメント比が大きいほど、また部材が乾燥しやすい環境にあるほど大きくなる。断面寸法が大きい部材では乾燥が内部まで進みにくいため、乾燥収縮もクリープも小さくなる。クリープはプレストレスの減少やたわみの増大の原因となる一方で、拘束による応力を緩和してひび割れを防ぐ有益な側面ももつ。\n\n【図解】乾燥収縮とクリープが大きくなる条件\n　要因｜乾燥収縮｜クリープ\n　単位水量が大きい｜大きくなる｜大きくなる\n　骨材量が多い｜小さくなる｜小さくなる\n　断面寸法が大きい｜小さくなる｜小さくなる\n　載荷材齢が早い｜ー｜大きくなる\n　⚠ 収縮するのはペースト。骨材は収縮を拘束する側である。',
