    correctKey: 'A',
    explanation: 'コンクリートの圧縮強度試験はJIS A 1108に規定される。供試体は直径の2倍の高さをもつ円柱形とし、直径は粗骨材の最大寸法の3倍以上かつ100ミリメートル以上とする。一般には直径100ミリメートル高さ200ミリメートル、または直径150ミリメートル高さ300ミリメートルが用いられる。供試体の作製はJIS A 1132により、突き棒または振動機で締め固め、上面を平滑に仕上げる。標準養生は水中または湿潤状態で温度20度プラスマイナス2度に保つ。載荷は圧縮応力度の増加が毎秒0.6プラスマイナス0.4ニュートン毎平方ミリメートルとなる速度で行い、最大荷重を断面積で除して圧縮強度を求める。高さと直径の比が2に満たない場合、拘束効果により見かけの強度が高く出るため補正係数を乗じる。試験結果の代表値は通常3個の供試体の平均値とする。\n\n【図解】圧縮強度試験の要点\n　・供試体の形状 → 高さは直径の2倍\n　・供試体の直径 → 粗骨材最大寸法の3倍以上かつ100ミリメートル以上\n　・標準養生 → 水中20度プラスマイナス2度\n　・載荷速度 → 毎秒0.6プラスマイナス0.4ニュートン毎平方ミリメートル\n　⚠ 高さと直径の比が2未満なら補正係数を乗じる。',
