    explanation: '高流動コンクリートは、フレッシュ時に高い流動性をもちながら材料分離を生じず、締固め作業を行わなくても型枠の隅々まで充填される自己充填性を有するコンクリートである。実現には、高性能AE減水剤により単位水量を増やすことなく流動性を高めることと、粘性を確保して粗骨材の沈降を防ぐことの両立が必要である。材料分離抵抗性の確保の方法により、粉体系、増粘剤系、併用系に分類される。粉体系は石灰石微粉末や高炉スラグ微粉末により単位粉体量を増やす方法、増粘剤系は水溶性高分子により粘性を高める方法である。流動性の評価にはスランプフロー試験を用い、目標値は一般に50から70センチメートル程度である。あわせて漏斗状の容器からの流下時間や、鉄筋を模した障害物を通過させるボックス試験により、間隙通過性を確認する。単位粗骨材かさ容積は普通コンクリートより小さく設定される。\n\n【図解】高流動コンクリートの分類\n　・粉体系 → 石灰石微粉末等で単位粉体量を増やす\n　・増粘剤系 → 水溶性高分子で粘性を高める\n　・併用系 → 粉体と増粘剤の両方を用いる\n　⚠ 評価はスランプではなくスランプフロー。目標は50から70センチメートル。',
    difficulty: 'basic',
