    explanation: 'スランプを大きくするには、混和剤を用いない限り単位水量を増やす必要がある。経験的に、スランプ1センチメートルの変化はおよそ単位水量の1.2パーセントの変化に対応するとされる。本問ではスランプを8センチメートルから12センチメートルへ4センチメートル大きくするので、単位水量の増加率は4かける1.2で4.8パーセントとなる。したがって増加量は165かける0.048で7.92キログラムであり、単位水量は165たす7.92で172.9、すなわち約173キログラムとなる。この値は単位水量の上限175キログラム毎立方メートルをかろうじて下回っているが、余裕は小さい。水セメント比を一定に保つためには単位セメント量も比例して増やす必要があり、乾燥収縮と水和熱の増大を招く。したがって実務では、単位水量を増やす代わりに高性能AE減水剤や流動化剤を用いてスランプを確保するのが基本である。\n\n【図解】スランプ変更にともなう単位水量の補正\n　項目｜計算｜結果\n　スランプの増加｜12−8｜4センチメートル\n　単位水量の増加率｜4×1.2｜4.8パーセント\n　増加量｜165×0.048｜7.9キログラム\n　補正後の単位水量｜165＋7.9｜約173キログラム\n　⚠ 水を増やすのではなく混和剤で対応するのが実務の基本である。',
