    explanation: '中性化残りとは、鉄筋位置までのかぶりから中性化深さを差し引いた、まだ中性化していない健全な層の厚さをいう。これが確保されている限り鉄筋は高アルカリ環境に保たれ、不動態被膜が維持されて腐食は生じない。本問ではかぶり40ミリメートルから中性化深さ28.3ミリメートルを引いて11.7ミリメートルとなり、必要とされる10ミリメートルを上回るため、設計耐用期間である50年にわたり中性化に対する所要の性能を確保できると判断される。土木学会示方書では、一般の環境で10ミリメートル、塩化物イオンの影響を受ける環境ではより大きな値を必要な中性化残りとして定めている。中性化残りが不足する場合には、かぶりを増やす、水セメント比を小さくして中性化速度係数を下げる、表面被覆により二酸化炭素の侵入を遮断するといった対策をとる。\n\n【図解】中性化残りの計算\n　項目｜計算｜結果\n　かぶり｜ー｜40ミリメートル\n　50年後の中性化深さ｜ー｜28.3ミリメートル\n　中性化残り｜40−28.3｜11.7ミリメートル\n　判定｜11.7は10以上｜所要性能を満たす\n　⚠ 中性化残りは引き算である。足し算にすると意味が逆になる。',
