    correctKey: 'C',
    explanation: '塩害は、外部から侵入した塩化物イオン、またはコンクリート中に当初から含まれる塩化物イオンが鉄筋の不動態被膜を破壊し、腐食を引き起こす劣化現象である。配合上の対策は二つの方向から考える。第一は塩化物イオンの侵入を抑えることで、水セメント比を小さくして毛細管空隙を減らし拡散係数を下げること、高炉スラグ微粉末やフライアッシュを用いてポゾラン反応や潜在水硬性により組織を緻密化すること、単位水量を低減することが有効である。とくに高炉スラグ微粉末を用いると塩化物イオンの拡散係数が数分の1に低下する。第二は初期の塩化物イオン量を抑えることで、JIS A 5308に定める0.30キログラム毎立方メートル以下を厳守する。これに対し、単位水量を増やすことは充填性の面では有利に見えても、組織を粗にして塩化物イオンの浸透を促進するため対策とはならない。\n\n【図解】塩害に対する配合上の対策\n　・水セメント比の低減 → 拡散係数の低下\n　・混和材の使用 → 高炉スラグ微粉末、フライアッシュによる緻密化\n　・初期塩化物イオン量の抑制 → 0.30キログラム毎立方メートル以下\n　・施工上の配慮 → かぶりの確保と確実な締固め\n　⚠ 充填性は単位水量ではなく混和剤とかぶり設計で確保する。',
