    correctKey: 'A',
    explanation: '温度ひび割れ指数は、マスコンクリートにおける温度ひび割れの発生しにくさを表す指標で、その材齢におけるコンクリートの引張強度を、温度変化によって生じる引張応力で除して定義される。したがって値が大きいほどひび割れが生じにくく安全側である。土木学会示方書では、ひび割れを防止したい場合に1.85以上、ひび割れの発生をできるだけ制限したい場合に1.4以上、有害なひび割れの発生を制限したい場合に1.0以上という目安を示している。指数が1.0であってもひび割れ発生確率は約50パーセントであり、絶対に生じないという意味ではない。指数を大きくするには、低発熱形セメントの使用、単位セメント量の低減、打込み温度の低下、パイプクーリング、打継ぎ位置や打込み区画の工夫、膨張材の使用、鉄筋によるひび割れ幅の制御といった対策を組み合わせる。\n\n【図解】温度ひび割れ指数の目安\n　・ひび割れを防止したい → 1.85以上\n　・発生をできるだけ制限したい → 1.4以上\n　・有害なひび割れを制限したい → 1.0以上\n　⚠ 分子が引張強度、分母が温度応力。大きいほど安全である。',
