    explanation: 'コンクリートの配合の表し方には示方配合と現場配合がある。示方配合は、粗骨材の最大寸法、スランプ、空気量、水セメント比、細骨材率、および水、セメント、細骨材、粗骨材、混和材料の単位量を示したもので、骨材が表面乾燥飽水状態にあること、細骨材は5ミリメートルふるいをすべて通り、粗骨材は5ミリメートルふるいにすべてとどまることを前提としている。これは配合を材料の状態に左右されない形で規定するためである。これに対し現場配合は、示方配合を実際に使用する材料の状態に合わせて修正したもので、骨材の粒度に関する補正と表面水に関する補正の二段階を経て求められる。現場配合における骨材の質量は、実際に計量する湿潤状態の質量である。両者を混同すると計量値を誤り、水セメント比が設計値からずれる原因となる。\n\n【図解】示方配合と現場配合\n　項目｜示方配合｜現場配合\n　骨材の含水状態｜表面乾燥飽水状態｜実際の湿潤状態\n　骨材の粒度｜5ミリメートルで完全に分かれる｜実際の粒度\n　用途｜配合の規定｜実際の計量\n　⚠ 換算は粒度補正と表面水補正の二段階で行う。',
    difficulty: 'standard',
