    explanation: '高流動コンクリートの配合設計は、高い流動性と材料分離抵抗性の両立を目標とする。粉体系の場合、単位粉体量を通常より大きく、一般には500から600キログラム毎立方メートル程度に設定して粘性を確保する。粉体にはセメントのほか石灰石微粉末、高炉スラグ微粉末、フライアッシュが用いられる。同時に、鉄筋間の間隙通過性を確保するため単位粗骨材かさ容積を小さく設定し、普通コンクリートの0.60から0.65立方メートル程度に対して0.28から0.35立方メートル程度とする。単位水量は高性能AE減水剤の使用により抑えられ、むしろ普通コンクリートと同等かそれ以下となる。品質の評価は、流動性についてスランプフロー試験、粘性について漏斗からの流下時間、間隙通過性についてボックス形容器を用いた試験を組み合わせて行う。締固め不要で施工できるため、過密配筋部材や騒音制約のある現場に有効である。\n\n【図解】高流動コンクリートの配合の特徴\n　項目｜普通コンクリート｜高流動コンクリート\n　単位粉体量｜300キログラム前後｜500から600キログラム\n　単位粗骨材かさ容積｜0.60から0.65立方メートル｜0.28から0.35立方メートル\n　流動性の評価｜スランプ｜スランプフロー\n　⚠ 粗骨材を減らして粉体を増やすのが基本的な考え方である。',
